// Grafana's API root: "" on prod, "/grafana" on staging.
const base = window.grafanaBootData?.settings?.appSubUrl || '';
const path = base + '/api/datasources/proxy/uid/devlake-api/rest/user-project-mappings/';

// Calls go via Grafana's datasource proxy, which attaches the DevLake API key
// server-side and strips cookies. See provisioning/datasources/datasource.yml.
//
// Variables are read at runtime, not interpolated: values reach this source before
// it compiles, so a quote or backslash in one is a syntax error. Keep the name
// split across the + or this line becomes a variable reference itself.
const readVar = (name) => context.grafana.templateService.replace('${' + name + '}');
const userLogin = readVar('userLogin');
const project = readVar('project');

return (async () => {
  const res = await fetch(path + encodeURIComponent(userLogin), {
    method: 'POST',
    credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ projectName: project }),
  });

  if (res.ok) {
    context.grafana.notifySuccess(['Mapping Added', userLogin + ' → ' + project]);
    context.grafana.refresh();
  } else {
    context.grafana.notifyError(['Error', 'HTTP ' + res.status + ': ' + (await res.text())]);
  }
})();

// Grafana's API root: "" on prod, "/grafana" on staging.
const base = window.grafanaBootData?.settings?.appSubUrl || '';
const path = base + '/api/datasources/proxy/uid/devlake-api/rest/user-project-mappings/';

// Calls go via Grafana's datasource proxy, which attaches the DevLake API key
// server-side and strips cookies. See provisioning/datasources/datasource.yml.
//
// Variables are read at runtime, not interpolated: values reach this source before
// it compiles, so a quote or backslash in one is a syntax error. Keep the name
// split across the + or this line becomes a variable reference itself.
const readVar = (name) => context.grafana.templateService.replace('${' + name + '}');
const userLogin = readVar('userLogin');
const project = readVar('project');

return (async () => {
  const res = await fetch(
    path + encodeURIComponent(userLogin) + '/' + encodeURIComponent(project),
    { method: 'DELETE', credentials: 'same-origin' },
  );

  if (res.ok) {
    context.grafana.notifySuccess(['Mapping Removed', userLogin + ' → ' + project]);
    context.grafana.refresh();
  } else {
    context.grafana.notifyError(['Error', 'HTTP ' + res.status + ': ' + (await res.text())]);
  }
})();
